def disconnect(
    self,
) -> None:
    """
    Release provider resources.
    """

def __init__(
    self,
    *,
    base_url: str = DEFAULT_BASE_URL,
    timeout_seconds: float = (
        DEFAULT_TIMEOUT_SECONDS
    ),
    retry_attempts: int = (
        DEFAULT_RETRY_ATTEMPTS
    ),
    retry_backoff_seconds: float = (
        DEFAULT_RETRY_BACKOFF_SECONDS
    ),
    maximum_candle_limit: int = (
        DEFAULT_MAXIMUM_CANDLE_LIMIT
    ),
    session: Session | None = None,
    connection_test_symbol: str = "BTCUSDT",
) -> None:
    self._base_url = self._validate_base_url(
        base_url
    )

    self._timeout_seconds = (
        self._validate_positive_float(
            timeout_seconds,
            field_name="timeout_seconds",
        )
    )

    self._retry_attempts = (
        self._validate_retry_attempts(
            retry_attempts
        )
    )

    self._retry_backoff_seconds = (
        self._validate_non_negative_float(
            retry_backoff_seconds,
            field_name=(
                "retry_backoff_seconds"
            ),
        )
    )

    self._maximum_candle_limit = (
        self._validate_maximum_candle_limit(
            maximum_candle_limit
        )
    )

    self._connection_test_symbol = (
        self._normalize_symbol(
            connection_test_symbol
        )
    )

    self._session = (
        session
        if session is not None
        else requests.Session()
    )

    self._owns_session = (
        session is None
    )

    self._connected = False

    self._closed = False

    self._lock = threading.RLock()

    logger.info(
        "%s v%s initialized.",
        self.PROVIDER_NAME,
        self.VERSION,
    )

def connect(
    self,
) -> bool:
    """
    Validate public Binance connectivity.

    No authentication or private account request is made.
    """

    with self._lock:
        if self._closed:
            raise MarketDataConnectionError(
                "Binance public provider has already "
                "been permanently closed."
            )

        if self._connected:
            return True

    try:
        self.get_price(
            self._connection_test_symbol
        )

    except Exception as error:
        with self._lock:
            self._connected = False

        raise MarketDataConnectionError(
            "Binance public connectivity test failed."
        ) from error

    with self._lock:
        self._connected = True

    logger.info(
        "%s connected successfully.",
        self.PROVIDER_NAME,
    )

    return True

def get_price(
    self,
    symbol: str,
) -> MarketPrice:
    """
    Fetch and normalize the latest symbol price.
    """

    normalized_symbol = (
        self._normalize_symbol(
            symbol
        )
    )

    payload = self._request_json(
        endpoint="/api/v3/ticker/price",
        params={
            "symbol": normalized_symbol,
        },
    )

    if not isinstance(
        payload,
        Mapping,
    ):
        raise MarketDataResponseError(
            "Binance ticker response must be "
            "a JSON object."
        )

    response_symbol = (
        self._normalize_symbol(
            str(
                payload.get(
                    "symbol",
                    normalized_symbol,
                )
            )
        )
    )

    if (
        response_symbol
        != normalized_symbol
    ):
        raise MarketDataResponseError(
            "Binance ticker response symbol does "
            "not match the requested symbol."
        )

    price = self._parse_positive_float(
        payload.get(
            "price"
        ),
        field_name="price",
        exception_type=InvalidPriceError,
    )

    with self._lock:
        self._connected = True

    return MarketPrice(
        symbol=normalized_symbol,
        price=price,
        provider=self.PROVIDER_NAME,
        received_at=utc_now(),
        source_timestamp=None,
        metadata={
            "endpoint": (
                "/api/v3/ticker/price"
            ),
        },
    )

def get_candles(
    self,
    symbol: str,
    timeframe: str = "5m",
    limit: int = 100,
) -> Sequence[MarketCandle]:
    """
    Fetch and normalize Binance OHLCV candles.
    """

    normalized_symbol = (
        self._normalize_symbol(
            symbol
        )
    )

    normalized_timeframe = (
        self._normalize_timeframe(
            timeframe
        )
    )

    normalized_limit = (
        self._validate_candle_limit(
            limit
        )
    )

    payload = self._request_json(
        endpoint="/api/v3/klines",
        params={
            "symbol": normalized_symbol,
            "interval": normalized_timeframe,
            "limit": normalized_limit,
        },
    )

    if not isinstance(
        payload,
        list,
    ):
        raise MarketDataResponseError(
            "Binance kline response must be "
            "a JSON array."
        )

    candles: list[
        MarketCandle
    ] = []

    for index, raw_candle in enumerate(
        payload
    ):
        try:
            candle = self._parse_candle(
                raw_candle,
                symbol=normalized_symbol,
                timeframe=(
                    normalized_timeframe
                ),
            )

        except (
            InvalidCandleError,
            MarketDataResponseError,
            TypeError,
            ValueError,
            IndexError,
        ) as error:
            raise InvalidCandleError(
                "Invalid Binance candle at index "
                f"{index}: {error}"
            ) from error

        candles.append(
            candle
        )

    candles.sort(
        key=lambda item: item.open_time
    )

    with self._lock:
        self._connected = True

    return tuple(
        candles
    )

def _on_start(
    self,
) -> None:
    try:
        connected = self._provider.connect()

        if not connected:
            raise MarketDataProviderUnavailableError(
                "Market-data provider returned "
                "an unsuccessful connection result."
            )

        started_at = utc_now()

        with self._lock:
            self._service_started_at = (
                started_at
            )

            self._consecutive_failures = 0

            self._degradation_active = False

        self._set_provider_connected_metric(
            True
        )

        self._publish_event(
            MarketFeedEventType.SERVICE_STARTED,
            payload={
                "provider": (
                    self.provider_name
                ),
                "version": self.VERSION,
                "started_at": (
                    started_at.isoformat()
                ),
            },
        )

        logger.info(
            "%s started successfully.",
            self.SERVICE_NAME,
        )

    except Exception as error:
        self._set_provider_connected_metric(
            False
        )

        self._publish_event(
            (
                MarketFeedEventType
                .SERVICE_START_FAILED
            ),
            severity=EventSeverity.CRITICAL,
            payload={
                "provider": (
                    self.provider_name
                ),
                "error_type": (
                    type(error).__name__
                ),
                "error": str(
                    error
                ),
            },
        )

        raise MarketDataServiceStartupError(
            "MarketFeedService startup failed."
        ) from error

def _on_stop(
    self,
) -> None:
    try:
        self._provider.disconnect()

        self._set_provider_connected_metric(
            False
        )

        stopped_at = utc_now()

        self._publish_event(
            MarketFeedEventType.SERVICE_STOPPED,
            payload={
                "provider": (
                    self.provider_name
                ),
                "stopped_at": (
                    stopped_at.isoformat()
                ),
            },
        )

        logger.info(
            "%s stopped successfully.",
            self.SERVICE_NAME,
        )

    except Exception as error:
        self._publish_event(
            (
                MarketFeedEventType
                .SERVICE_STOP_FAILED
            ),
            severity=EventSeverity.ERROR,
            payload={
                "provider": (
                    self.provider_name
                ),
                "error_type": (
                    type(error).__name__
                ),
                "error": str(
                    error
                ),
            },
        )

        raise MarketDataServiceShutdownError(
            "MarketFeedService shutdown failed."
        ) from error

def health(self) -> HealthReport:
    """
    Return a standardized service health report.
    """

    with self._lock:

        state = self._state

        if state == ServiceState.RUNNING:
            status = HealthStatus.HEALTHY
            message = "Service is operating normally."

        elif state == ServiceState.DEGRADED:
            status = HealthStatus.DEGRADED
            message = "Service is operational but degraded."

        elif state == ServiceState.FAILED:
            status = HealthStatus.UNHEALTHY
            message = (
                self._last_error
                or "Service lifecycle failed."
            )

        elif state in {
            ServiceState.CREATED,
            ServiceState.STOPPED,
        }:
            status = HealthStatus.UNKNOWN
            message = "Service is not currently running."

        else:
            status = HealthStatus.UNKNOWN
            message = (
                f"Service lifecycle transition: "
                f"{state.value}."
            )

        details = dict(
            self._health_details()
        )

        if self._last_error is not None:
            details.setdefault(
                "last_error",
                self._last_error,
            )

        return HealthReport(
            service_name=self.identity.name,
            status=status,
            state=state,
            message=message,
            details=details,
        )
